INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'celebrate', 'v.', '/ˈselɪbreɪt/', '庆祝;庆贺', 'Families gather to celebrate the festival together every year.', '每年家人都聚在一起庆祝这个节日。', 'Festivals and Celebrations', 1, 0, 'senior', 'wordlist', 'required3', 'U1', 'celebrate a festival', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'celebration', 'n.', '/ˌselɪˈbreɪʃn/', '庆祝;庆典;庆祝活动', 'The whole town joined in the New Year celebration.', '全城都参加了新年庆典。', 'Festivals and Celebrations', 2, 0, 'senior', 'wordlist', 'required3', 'U1', 'festivals and celebrations', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'ceremony', 'n.', '/ˈserəməni/', '典礼;仪式', 'The opening ceremony of the festival was truly amazing.', '节日的开幕仪式真是令人惊叹。', 'Festivals and Celebrations', 3, 0, 'senior', 'wordlist', 'required3', 'U1', 'the opening ceremony', '美音 /ˈserəmoʊni/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'occasion', 'n.', '/əˈkeɪʒn/', '特别的事情(或仪式、庆典);机会;场合', 'A wedding is a happy occasion for the whole family.', '婚礼对全家来说是一个喜庆的场合。', 'Festivals and Celebrations', 4, 0, 'senior', 'wordlist', 'required3', 'U1', 'a special occasion', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'origin', 'n.', '/ˈɒrɪdʒɪn/', '起源;起因;出身', 'Few people know the true origin of this ancient festival.', '很少有人知道这个古老节日的真正起源。', 'Festivals and Celebrations', 5, 0, 'senior', 'wordlist', 'required3', 'U1', 'the origin of the festival', '美音 /ˈɔːrɪdʒɪn/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'custom', 'n.', '/ˈkʌstəm/', '习俗;风俗;习惯', 'Lighting firecrackers is a typical Spring Festival custom.', '放鞭炮是春节的一个典型习俗。', 'Festivals and Celebrations', 6, 0, 'senior', 'wordlist', 'required3', 'U1', 'a local custom', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'tradition', 'n.', '/trəˈdɪʃn/', '传统;惯例', 'Frightening away evil spirits is part of the tradition.', '驱赶恶灵是这一传统的一部分。', 'Festivals and Celebrations', 7, 0, 'senior', 'wordlist', 'required3', 'U1', 'keep a tradition', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'traditional', 'adj.', '/trəˈdɪʃənl/', '传统的;惯例的', 'People wear traditional costumes during the festival.', '人们在节日期间穿着传统服装。', 'Festivals and Celebrations', 8, 0, 'senior', 'wordlist', 'required3', 'U1', 'traditional costumes', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'religion', 'n.', '/rɪˈlɪdʒən/', '宗教;宗教信仰', 'Some festivals come from religion, others from the seasons.', '有些节日源于宗教,有些则源于季节。', 'Festivals and Celebrations', 9, 0, 'senior', 'wordlist', 'required3', 'U1', 'different religions', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'religious', 'adj.', '/rɪˈlɪdʒəs/', '宗教的;笃信宗教的', 'Halloween became a fun festival in spite of its religious origins.', '尽管万圣节有宗教渊源,它还是变成了一个有趣的节日。', 'Festivals and Celebrations', 10, 0, 'senior', 'wordlist', 'required3', 'U1', 'religious origins', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'harvest', 'n./v.', '/ˈhɑːvɪst/', '收获季节;收成;收割', 'The harvest festival is held after the crops are gathered in.', '丰收节在庄稼收割之后举行。', 'Festivals and Celebrations', 11, 0, 'senior', 'wordlist', 'required3', 'U1', 'the harvest festival', '美音 /ˈhɑːrvɪst/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'crop', 'n.', '/krɒp/', '庄稼;作物;一季的收成', 'People celebrate when all the crops have been gathered in.', '当所有庄稼都收割完毕时,人们便庆祝。', 'Festivals and Celebrations', 12, 0, 'senior', 'wordlist', 'required3', 'U1', 'gather the crops', '美音 /krɑːp/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'gather', 'v.', '/ˈɡæðə(r)/', '聚集;收集;收割', 'Families gather to admire the shining moon at the Mid-Autumn Festival.', '中秋节时家人聚在一起赏明月。', 'Festivals and Celebrations', 13, 0, 'senior', 'wordlist', 'required3', 'U1', 'gather together', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'grateful', 'adj.', '/ˈɡreɪtfl/', '感激的;表示感谢的', 'People celebrate to show they are grateful for the food.', '人们庆祝是为了表达对食物的感激。', 'Festivals and Celebrations', 14, 0, 'senior', 'wordlist', 'required3', 'U1', 'be grateful for', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'gratitude', 'n.', '/ˈɡrætɪtjuːd/', '感激之情;感谢', 'The festival is a way of showing gratitude for the harvest.', '这个节日是表达对丰收感激之情的一种方式。', 'Festivals and Celebrations', 15, 0, 'senior', 'wordlist', 'required3', 'U1', 'show gratitude', '美音 /ˈɡrætɪtuːd/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'joy', 'n.', '/dʒɔɪ/', '高兴;喜悦', 'The spirit of sharing joy is common in all festivals.', '分享喜悦的精神是所有节日共有的。', 'Festivals and Celebrations', 16, 0, 'senior', 'wordlist', 'required3', 'U1', 'share joy', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'joyful', 'adj.', '/ˈdʒɔɪfl/', '高兴的;快乐的', 'The Lantern Festival is a joyful occasion for everyone.', '元宵节对每个人来说都是一个欢乐的日子。', 'Festivals and Celebrations', 17, 0, 'senior', 'wordlist', 'required3', 'U1', 'a joyful occasion', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'merry', 'adj.', '/ˈmeri/', '愉快的;高兴的', 'People sing carols and wish each other a merry Christmas.', '人们唱颂歌,互祝圣诞快乐。', 'Festivals and Celebrations', 18, 0, 'senior', 'wordlist', 'required3', 'U1', 'Merry Christmas', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'decorate', 'v.', '/ˈdekəreɪt/', '装饰;装潢', 'People decorate churches and town halls with flowers and fruit.', '人们用鲜花和水果装饰教堂和市政厅。', 'Festivals and Celebrations', 19, 0, 'senior', 'wordlist', 'required3', 'U1', 'decorate the church', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'lantern', 'n.', '/ˈlæntən/', '灯笼;提灯', 'Floating lanterns light up the whole river at night.', '漂浮的灯笼在夜里照亮了整条河。', 'Festivals and Celebrations', 20, 0, 'senior', 'wordlist', 'required3', 'U1', 'a lantern fair', '美音 /ˈlæntərn/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'firework', 'n.', '/ˈfaɪəwɜːk/', '烟火;烟花;[pl.]烟花表演', 'The beautiful fireworks lit up the night sky over the city.', '绚丽的烟花照亮了城市的夜空。', 'Festivals and Celebrations', 21, 0, 'senior', 'wordlist', 'required3', 'U1', 'watch the fireworks', '美音 /ˈfaɪərwɜːrk/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'firecracker', 'n.', '/ˈfaɪəkrækə(r)/', '鞭炮;爆竹', 'Lighting firecrackers is said to drive away evil spirits.', '据说放鞭炮能驱赶恶灵。', 'Festivals and Celebrations', 22, 0, 'senior', 'wordlist', 'required3', 'U1', 'light firecrackers', '美音 /ˈfaɪərkrækər/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'costume', 'n.', '/ˈkɒstjuːm/', '(某地或某历史时期的)服装;戏装', 'Dancers in colourful costumes marched along the streets.', '穿着五彩服装的舞者沿街游行。', 'Festivals and Celebrations', 23, 0, 'senior', 'wordlist', 'required3', 'U1', 'carnival costumes', '美音 /ˈkɑːstuːm/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'march', 'v./n.', '/mɑːtʃ/', '行进;前进;游行', 'Crowds march along the streets during the carnival.', '狂欢节期间人群沿街行进。', 'Festivals and Celebrations', 24, 0, 'senior', 'wordlist', 'required3', 'U1', 'march along the streets', '美音 /mɑːrtʃ/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'wedding', 'n.', '/ˈwedɪŋ/', '婚礼;结婚庆典', 'A wedding is one of the most important family celebrations.', '婚礼是最重要的家庭庆典之一。', 'Festivals and Celebrations', 25, 0, 'senior', 'wordlist', 'required3', 'U1', 'a wedding ceremony', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'eve', 'n.', '/iːv/', '前夕;前一天', 'On New Year''s Eve, all the family members get together.', '除夕之夜,全家人都聚在一起。', 'Festivals and Celebrations', 26, 0, 'senior', 'wordlist', 'required3', 'U1', 'New Year''s Eve', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'envelope', 'n.', '/ˈenvələʊp/', '信封;封套', 'Children get lucky money in red envelopes from their relatives.', '孩子们从亲戚那里得到装在红包里的压岁钱。', 'Festivals and Celebrations', 27, 0, 'senior', 'wordlist', 'required3', 'U1', 'a red envelope', '美音 /ˈenvəloʊp/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'turkey', 'n.', '/ˈtɜːki/', '火鸡;火鸡肉', 'Roast turkey is the main dish at a Thanksgiving dinner.', '烤火鸡是感恩节晚餐的主菜。', 'Festivals and Celebrations', 28, 0, 'senior', 'wordlist', 'required3', 'U1', 'roast turkey', '美音 /ˈtɜːrki/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'feature', 'n./v.', '/ˈfiːtʃə(r)/', '特色;特征;以……为特色', 'The ancient harvest festival featured a parade and a great feast.', '古代的丰收节以游行和盛大的宴会为特色。', 'Festivals and Celebrations', 29, 0, 'senior', 'wordlist', 'required3', 'U1', 'feature a parade', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'reflect', 'v.', '/rɪˈflekt/', '反映;显示;反射', 'Festivals reflect people''s wishes, beliefs and attitudes towards life.', '节日反映了人们的愿望、信念和对生活的态度。', 'Festivals and Celebrations', 30, 0, 'senior', 'wordlist', 'required3', 'U1', 'reflect people''s wishes', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'represent', 'v.', '/ˌreprɪˈzent/', '象征;代表;相当于', 'The colour red represents good luck in Chinese culture.', '在中国文化中,红色象征好运。', 'Festivals and Celebrations', 31, 0, 'senior', 'wordlist', 'required3', 'U1', 'represent good luck', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'significant', 'adj.', '/sɪɡˈnɪfɪkənt/', '有重大意义的;显著的', 'Customs play a significant role in every festival.', '习俗在每个节日中都起着重要作用。', 'Festivals and Celebrations', 32, 0, 'senior', 'wordlist', 'required3', 'U1', 'play a significant role', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'typical', 'adj.', '/ˈtɪpɪkl/', '典型的;有代表性的;平常的', 'Lighting firecrackers is a typical custom of the Spring Festival.', '放鞭炮是春节的一个典型习俗。', 'Festivals and Celebrations', 33, 0, 'senior', 'wordlist', 'required3', 'U1', 'a typical custom', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'region', 'n.', '/ˈriːdʒən/', '地区;区域;地方', 'Different regions celebrate the same festival in different ways.', '不同地区以不同方式庆祝同一个节日。', 'Festivals and Celebrations', 34, 0, 'senior', 'wordlist', 'required3', 'U1', 'different regions', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'commercial', 'adj.', '/kəˈmɜːʃl/', '商业(化)的;以获利为目的的', 'Some people worry that festivals are becoming too commercial.', '有些人担心节日正变得过于商业化。', 'Festivals and Celebrations', 35, 0, 'senior', 'wordlist', 'required3', 'U1', 'become commercial', '美音 /kəˈmɜːrʃl/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'commercialise', 'v.', '/kəˈmɜːʃəlaɪz/', '使商业化;利用……牟利', 'Many people debate whether festivals should be commercialised.', '许多人争论节日是否应该被商业化。', 'Festivals and Celebrations', 36, 0, 'senior', 'wordlist', 'required3', 'U1', 'commercialise festivals', '美式拼 commercialize;美音 /kəˈmɜːrʃəlaɪz/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'fade', 'v.', '/feɪd/', '逐渐消失;(使)褪色;(身体)变虚弱', 'With the spread of new ideas, some old customs may fade away.', '随着新观念的传播,一些旧习俗可能会逐渐消失。', 'Festivals and Celebrations', 37, 0, 'senior', 'wordlist', 'required3', 'U1', 'fade away', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'evil', 'adj./n.', '/ˈiːvl/', '邪恶的;有害的;邪恶;罪恶', 'Firecrackers are lit to drive away the evil spirits.', '燃放鞭炮是为了驱赶恶灵。', 'Festivals and Celebrations', 38, 0, 'senior', 'wordlist', 'required3', 'U1', 'evil spirits', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'faith', 'n.', '/feɪθ/', '宗教信仰;信任;相信', 'Festivals reflect people''s beliefs and faiths.', '节日反映了人们的信念和信仰。', 'Festivals and Celebrations', 39, 0, 'senior', 'wordlist', 'required3', 'U1', 'people''s faiths', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'respect', 'n./v.', '/rɪˈspekt/', '尊敬;尊重', 'On this day people show respect to the elderly.', '在这一天人们向长辈表示尊敬。', 'Festivals and Celebrations', 40, 0, 'senior', 'wordlist', 'required3', 'U1', 'show respect', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'riddle', 'n.', '/ˈrɪdl/', '谜语;神秘事件', 'During the Lantern Festival, people enjoy guessing riddles.', '元宵节期间,人们喜欢猜灯谜。', 'Festivals and Celebrations', 41, 0, 'senior', 'wordlist', 'required3', 'U1', 'guess riddles', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'moment', 'n.', '/ˈməʊmənt/', '片刻;瞬间;时刻', 'That was the moment I understood why people love this festival.', '正是那一刻,我明白了人们为何热爱这个节日。', 'Festivals and Celebrations', 42, 0, 'senior', 'wordlist', 'required3', 'U1', 'a special moment', '美音 /ˈmoʊmənt/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'charm', 'n.', '/tʃɑːm/', '魅力;迷人的特征', 'Every festival has its own customs and unique charm.', '每个节日都有自己的习俗和独特魅力。', 'Festivals and Celebrations', 43, 0, 'senior', 'wordlist', 'required3', 'U1', 'unique charm', '美音 /tʃɑːrm/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'lunar', 'adj.', '/ˈluːnə(r)/', '阴历的;月球的;月亮的', 'The festival falls on a fixed day of the lunar calendar.', '这个节日落在阴历的某个固定日子。', 'Festivals and Celebrations', 44, 0, 'senior', 'wordlist', 'required3', 'U1', 'the lunar calendar', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'wrestle', 'v.', '/ˈresl/', '摔跤;奋力对付', 'Strong men wrestle on the green field during the festival.', '节日期间,壮汉们在绿色的场地上摔跤。', 'Festivals and Celebrations', 45, 0, 'senior', 'wordlist', 'required3', 'U1', 'wrestle on the field', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'grace', 'n.', '/ɡreɪs/', '优美;优雅;高雅', 'I was moved by the dancers'' show of strength and grace.', '舞者们展现的力量与优雅令我深受感动。', 'Festivals and Celebrations', 46, 0, 'senior', 'wordlist', 'required3', 'U1', 'show grace', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'set off', 'phr.', '/set ɒf/', '出发;动身;燃放(烟花)', 'We set off early to reach the festival before sunrise.', '我们一早就动身,以便在日出前赶到节日现场。', 'Festivals and Celebrations', 47, 0, 'senior', 'wordlist', 'required3', 'U1', 'set off early', '美音 /set ɔːf/');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('r3u1.01', '①V-ing 作表语(描述事物给人的感受)', 'A2', 10, '必修三 U1 — 现在分词作表语,放在 be 等系动词后,说明主语(常为事物)所具有的、令人产生某种感受的性质。物用 -ing(amazing/exciting),人用 -ed(amazed/excited)。', 1, 'required3', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('r3u1.02', '②V-ing 作前置定语(主动/正在进行)', 'A2', 10, '必修三 U1 — 现在分词放在名词前作定语,表示该名词主动发出动作或动作正在进行(exciting news, the rising sun, running water),相当于一个主动、进行的形容词。', 2, 'required3', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('r3u1.03', '③V-ing 作后置定语(= who/which is doing)', 'A2', 10, '必修三 U1 — 现在分词(短语)放在名词后作定语,相当于一个主动的定语从句(the man standing there = who is standing there),被修饰名词是动作的发出者。', 3, 'required3', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.01'), 'These floating lanterns on the river are truly ____.', 'amazing', 'amazed', 'to amaze', 'amaze', 'A', '主语 lanterns 是事物,描述它给人的感受 → 用 -ing 形 amazing;-ed 形 amazed 只形容人。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.01'), 'The dragon dance at the festival was really ____.', 'excited', 'exciting', 'to excite', 'excite', 'B', '主语 dragon dance 是事物,作表语描述其令人兴奋的性质 → exciting。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.01'), 'The story behind this old custom is very ____.', 'touched', 'to touch', 'touching', 'touch', 'C', '主语 story 是事物,作表语 → touching(令人感动的);touched 形容人。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.01'), 'To be honest, the long parade became a little ____ after two hours.', 'to bore', 'bore', 'bored', 'boring', 'D', '主语 parade 是事物 → boring(令人厌烦的);bored 形容人感到厌烦。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.01'), 'The fireworks over the city were absolutely ____.', 'stunning', 'stunned', 'to stun', 'stun', 'A', '主语 fireworks 是事物,作表语 → stunning(惊艳的)。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.01'), 'The atmosphere at the carnival was so ____ that nobody wanted to leave.', 'relaxed', 'relaxing', 'to relax', 'relax', 'B', '主语 atmosphere 是事物 → relaxing(令人放松的)。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.01'), 'The noise of the firecrackers all night was quite ____.', 'annoyed', 'to annoy', 'annoying', 'annoy', 'C', '主语 noise 是事物 → annoying(令人心烦的);annoyed 形容人。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.01'), 'The way they wash the streets clean after the tomato fight is ____.', 'to surprise', 'surprise', 'surprised', 'surprising', 'D', '主语 the way... 是事物 → surprising(令人惊讶的)。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.01'), 'The horse races at the Naadam Festival are truly ____.', 'thrilling', 'thrilled', 'to thrill', 'thrill', 'A', '主语 races 是事物 → thrilling(惊险刺激的)。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.01'), 'The samba performance was so ____ that the crowd cheered loudly.', 'amazed', 'amazing', 'to amaze', 'amaze', 'B', '主语 performance 是事物 → amazing。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.01'), 'The food festival sounded ____, but they didn''t actually eat anything.', 'interested', 'to interest', 'interesting', 'interest', 'C', '主语 festival 是事物 → interesting(有趣的);interested 形容人。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.01'), 'Watching the lanterns float away was a deeply ____ experience.', 'to move', 'move', 'moved', 'moving', 'D', 'experience 是事物 → moving(感人的);moved 形容人被感动。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.01'), 'The whole opening ceremony was quite ____.', 'impressing', 'impressed', 'to impress', 'impress', 'A', '主语 ceremony 是事物 → impressing/impressive 类的 -ing 形 impressing(令人印象深刻)。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.01'), 'Honestly, the speeches before the dinner were a bit ____.', 'tired', 'tiring', 'to tire', 'tire', 'B', '主语 speeches 是事物 → tiring(令人疲惫的);tired 形容人。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.01'), 'The wrestlers'' show of strength and grace was truly ____.', 'inspired', 'to inspire', 'inspiring', 'inspire', 'C', '主语 show 是事物 → inspiring(鼓舞人心的)。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.01'), 'After dancing for hours in those heavy costumes, the day felt ____.', 'to exhaust', 'exhaust', 'exhausted', 'exhausting', 'D', '主语 day 是事物 → exhausting(令人筋疲力尽的)。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.01'), 'The colourful decorations in the square looked ____.', 'charming', 'charmed', 'to charm', 'charm', 'A', '主语 decorations 是事物 → charming(迷人的)。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.01'), 'The riddles at the lantern fair were both fun and ____.', 'puzzled', 'puzzling', 'to puzzle', 'puzzle', 'B', '主语 riddles 是事物 → puzzling(令人费解的);puzzled 形容人。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.01'), 'For first-time visitors, the festival can be quite ____.', 'overwhelmed', 'to overwhelm', 'overwhelming', 'overwhelm', 'C', '主语 festival 是事物 → overwhelming(令人难以招架的)。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.01'), 'The smell of roast turkey from the kitchen was really ____.', 'to tempt', 'tempt', 'tempted', 'tempting', 'D', '主语 smell 是事物 → tempting(诱人的)。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.02'), 'Families celebrating the Lunar New Year can enjoy ____ dragon dances.', 'exciting', 'excited', 'to excite', 'excite', 'A', '前置定语修饰 dances,表示舞蹈令人兴奋 → exciting。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.02'), 'We sat by the river and watched the ____ moon rise slowly.', 'risen', 'rising', 'to rise', 'rise', 'B', '前置定语,月亮正在升起(主动/进行)→ rising moon。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.02'), 'There was a ____ story behind every lantern at the fair.', 'touched', 'to touch', 'touching', 'touch', 'C', '前置定语,故事令人感动 → touching story。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.02'), 'Children love the ____ lights on the Christmas trees everywhere.', 'to shine', 'shine', 'shone', 'shining', 'D', '前置定语,灯光正在闪耀 → shining lights。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.02'), 'The ____ crowds filled every street during the carnival.', 'dancing', 'danced', 'to dance', 'dance', 'A', '前置定语,人群在跳舞(主动/进行)→ dancing crowds。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.02'), 'It is such a ____ time when the whole family gathers for dinner.', 'excited', 'exciting', 'to excite', 'excite', 'B', '前置定语修饰 time → exciting time。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.02'), 'The ____ moon over the village was the highlight of the night.', 'shone', 'to shine', 'shining', 'shine', 'C', '前置定语,月亮在发光 → shining moon。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.02'), 'We could hear the sound of ____ water in the temple garden.', 'to run', 'ran', 'run', 'running', 'D', 'running water 流动的水,前置定语表主动/进行。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.02'), 'The ____ news that the festival would be held again made everyone happy.', 'exciting', 'excited', 'to excite', 'excite', 'A', 'exciting news 令人兴奋的消息,前置定语。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.02'), 'The ____ samba music made it impossible to sit still.', 'beaten', 'beating', 'to beat', 'beat', 'B', '前置定语,音乐在跳动(主动/进行)→ beating music。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.02'), 'Everyone admired the ____ fireworks high above the river.', 'bursted', 'to burst', 'bursting', 'burst', 'C', '前置定语,烟花正在绽放 → bursting fireworks。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.02'), 'The ____ lanterns slowly drifted down the dark river.', 'to float', 'floated', 'float', 'floating', 'D', 'floating lanterns 漂浮的灯笼,前置定语表主动/进行。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.02'), 'It was a ____ sight to see thousands of lanterns in the sky.', 'amazing', 'amazed', 'to amaze', 'amaze', 'A', '前置定语修饰 sight → amazing sight。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.02'), 'The ____ fire dragon lit up the whole town square.', 'whirled', 'whirling', 'to whirl', 'whirl', 'B', '前置定语,火龙在旋舞(主动/进行)→ whirling dragon。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.02'), 'We followed the ____ parade through the old streets.', 'marched', 'to march', 'marching', 'march', 'C', '前置定语,游行队伍在行进 → marching parade。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.02'), 'The ____ smell of mooncakes filled the whole house.', 'to tempt', 'tempted', 'tempt', 'tempting', 'D', '前置定语,气味诱人 → tempting smell。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.02'), 'Their ____ performances on the green field amazed every visitor.', 'inspiring', 'inspired', 'to inspire', 'inspire', 'A', '前置定语,表演鼓舞人心 → inspiring performances。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.02'), 'The ____ crops in the autumn fields meant a good harvest festival.', 'ripened', 'ripening', 'to ripen', 'ripen', 'B', '前置定语,庄稼在成熟(主动/进行)→ ripening crops。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.02'), 'A ____ smile spread across every child''s face at the fair.', 'growed', 'to grow', 'growing', 'grow', 'C', '前置定语,笑容在扩大 → growing smile。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.02'), 'The ____ candles in the windows made the town look warm and bright.', 'to burn', 'burnt', 'burn', 'burning', 'D', 'burning candles 燃烧的蜡烛,前置定语表主动/进行。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.03'), 'The families ____ the Lunar New Year enjoyed delicious mooncakes together.', 'celebrating', 'celebrated', 'to celebrate', 'celebrate', 'A', '后置定语 = who were celebrating;families 主动庆祝 → celebrating。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.03'), 'Look at the lanterns ____ slowly down the river.', 'floated', 'floating', 'to float', 'float', 'B', '后置定语 = which are floating;灯笼主动漂浮 → floating。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.03'), 'The man ____ there in the fancy robe is the festival host.', 'stood', 'to stand', 'standing', 'stand', 'C', '后置定语 = who is standing;man 主动站立 → standing。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.03'), 'The number of people ____ part in the tomato fight can reach 20,000.', 'to take', 'took', 'take', 'taking', 'D', '后置定语 = who take part;people 主动参与 → taking。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.03'), 'I saw a lot of people ____ fancy Mongolian robes at the games.', 'wearing', 'worn', 'to wear', 'wear', 'A', '后置定语 = who were wearing;people 主动穿着 → wearing。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.03'), 'The dancers ____ their arms in the air looked just like eagles.', 'waved', 'waving', 'to wave', 'wave', 'B', '后置定语 = who were waving;dancers 主动挥臂 → waving。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.03'), 'The children ____ for Easter eggs were laughing with joy.', 'searched', 'to search', 'searching', 'search', 'C', '后置定语 = who were searching;children 主动寻找 → searching。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.03'), 'We watched the riders ____ their horses across the wide field.', 'to race', 'raced', 'race', 'racing', 'D', '后置定语 = who were racing;riders 主动赛马 → racing。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.03'), 'The crowds ____ along the streets sang and cheered all day.', 'marching', 'marched', 'to march', 'march', 'A', '后置定语 = who were marching;crowds 主动行进 → marching。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.03'), 'The friends ____ and talking around the table made the dinner lively.', 'laughed', 'laughing', 'to laugh', 'laugh', 'B', '后置定语 = who were laughing;friends 主动欢笑 → laughing。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.03'), 'The visitors ____ the samba dance could not stop clapping.', 'enjoyed', 'to enjoy', 'enjoying', 'enjoy', 'C', '后置定语 = who were enjoying;visitors 主动欣赏 → enjoying。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.03'), 'There were many tourists ____ photographs of the bright lanterns.', 'to take', 'took', 'take', 'taking', 'D', '后置定语 = who were taking;tourists 主动拍照 → taking。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.03'), 'The people ____ in the square wished each other a happy new year.', 'gathering', 'gathered', 'to gather', 'gather', 'A', '后置定语 = who were gathering;people 主动聚集 → gathering。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.03'), 'We admired the moon ____ brightly over the quiet village.', 'shone', 'shining', 'to shine', 'shine', 'B', '后置定语 = which was shining;moon 主动发光 → shining。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.03'), 'The wrestlers ____ onto the green field were greeted with loud cheers.', 'danced', 'to dance', 'dancing', 'dance', 'C', '后置定语 = who were dancing;wrestlers 主动起舞 → dancing。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.03'), 'The relatives ____ lucky money to the children made everyone smile.', 'to give', 'gave', 'give', 'giving', 'D', '后置定语 = who were giving;relatives 主动给压岁钱 → giving。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.03'), 'The students ____ traditional costumes performed a folk dance.', 'wearing', 'worn', 'to wear', 'wear', 'A', '后置定语 = who were wearing;students 主动穿戴 → wearing。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.03'), 'Everyone loved the choir ____ carols outside the church.', 'sang', 'singing', 'to sing', 'sing', 'B', '后置定语 = which was singing;choir 主动唱歌 → singing。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.03'), 'The villagers ____ the church with flowers worked happily together.', 'decorated', 'to decorate', 'decorating', 'decorate', 'C', '后置定语 = who were decorating;villagers 主动装饰 → decorating。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U1' AND code='r3u1.03'), 'I noticed several families ____ a great feast in the town hall.', 'to share', 'shared', 'share', 'sharing', 'D', '后置定语 = who were sharing;families 主动分享盛宴 → sharing。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'Why Do We Celebrate Festivals?', 'Festivals are celebrated all around the world, and they have a wide range of origins. Some come from the seasons of the year, some from religion, and others from famous figures or important events. Every festival has its own customs and unique charm. Yet no matter how different they may seem, the spirit of sharing joy, gratitude, love or peace is common to almost all of them. Festivals are an important part of society because they reflect people''s wishes, beliefs and attitudes towards life. They are happy occasions that allow us to relax, spend time with our families and forget about work for a little while. Studying festivals also helps us understand where we came from and who we are. In fact, if you look closely at the festivals of different cultures, you may be surprised to discover how much people everywhere actually have in common.', '说明·节日的起源与意义', 146, '[{"q":"According to the passage, where do festivals come from?","answer":"A","options":["From a wide variety of sources such as seasons and religion.","Only from religious beliefs.","Only from the change of the seasons.","From modern shopping habits."],"explanation":"原文 ''a wide range of origins... seasons... religion... famous figures or important events'' 的概括转述。"},{"q":"What do almost all festivals share, according to the writer?","answer":"B","options":["The same date every year.","A spirit of sharing positive feelings like joy and gratitude.","Exactly the same customs.","A focus on making money."],"explanation":"原文 ''the spirit of sharing joy, gratitude, love or peace is common'' 的转述。"},{"q":"What may surprise people who study festivals carefully?","answer":"A","options":["That different cultures share a great deal in common.","That festivals are dying out.","That no two cultures are alike.","That festivals have no real meaning."],"explanation":"末句 ''how much people everywhere actually have in common'' 的转述。"}]'::jsonb, '[{"word":"origin","cn":"起源"},{"word":"charm","cn":"魅力"},{"word":"gratitude","cn":"感激"},{"word":"reflect","cn":"反映"}]'::jsonb, 2, 'required3', 'U1');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'Harvest Festivals Around the World', 'Of all the traditional festivals, the harvest festival can be found in almost every culture. This important agricultural festival takes place after all the crops have been gathered in. People celebrate to show that they are grateful for the year''s supply of food. In ancient Egypt, the harvest festival was held during the springtime, which was the Egyptian harvest season. It featured a colourful parade and a great feast with music, dancing and sports. Today, in some European countries, people decorate their churches and town halls with flowers and fruit, and then get together to celebrate over a shared meal. In China, the Mid-Autumn Festival has a similar spirit. On that night, families gather to admire the bright round moon and enjoy delicious mooncakes. Although the customs differ from place to place, the idea behind every harvest festival is the same: to give thanks for nature''s gifts and to share happiness with the people we love.', '说明·世界各地的丰收节', 156, '[{"q":"When does a harvest festival usually take place?","answer":"B","options":["Before the seeds are planted.","Once the crops have all been collected.","In the middle of winter.","Only during a wedding."],"explanation":"原文 ''takes place after all the crops have been gathered in'' 的转述。"},{"q":"How did ancient Egyptians mark their harvest festival?","answer":"C","options":["By lighting firecrackers in winter.","By staying quietly at home.","With a parade and a large feast in spring.","By guessing riddles at a lantern fair."],"explanation":"原文 ''held during the springtime... featured a colourful parade and a great feast'' 的转述。"},{"q":"What does the writer say is the same about every harvest festival?","answer":"D","options":["The exact food that is eaten.","The country where it is held.","The date on which it falls.","The aim of giving thanks and sharing happiness."],"explanation":"末句 ''to give thanks for nature''s gifts and to share happiness'' 的转述。"}]'::jsonb, '[{"word":"harvest","cn":"收获"},{"word":"crop","cn":"庄稼"},{"word":"decorate","cn":"装饰"},{"word":"feast","cn":"盛宴"}]'::jsonb, 2, 'required3', 'U1');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'A Spring Festival at Home', 'For my family, the most important festival of the year is the Spring Festival. The celebration really begins on the eve of the Lunar New Year, when every family member, no matter how far away, tries to come home. My grandmother spends the whole day cooking, and the kitchen fills with tempting smells. In the evening we sit around one big table and share a special dinner. After the meal, my parents and relatives give the children lucky money in bright red envelopes, which always makes us cheer. In the past, people would light firecrackers to drive away evil spirits and welcome the new year, and the noise lasted all night long. Nowadays, many cities no longer allow firecrackers in order to avoid air pollution, so instead we watch shows on television and chat together. To be honest, the food and the fireworks matter less to me than the simple joy of having everyone in one room again.', '记叙·一家人的春节', 158, '[{"q":"When does the family''s Spring Festival celebration begin?","answer":"A","options":["On the night before the Lunar New Year.","A whole month after the new year.","Only on the morning of New Year''s Day.","During the summer holidays."],"explanation":"原文 ''begins on the eve of the Lunar New Year'' 的转述。"},{"q":"Why do many cities now ban firecrackers?","answer":"B","options":["Because they are too expensive.","To reduce air pollution.","Because no one likes them.","Because the law forgot about them."],"explanation":"原文 ''no longer allow firecrackers in order to avoid air pollution'' 的转述。"},{"q":"What matters most to the writer about the festival?","answer":"C","options":["The amount of lucky money.","The loud sound of firecrackers.","Being together with the whole family.","The shows shown on television."],"explanation":"末句 ''the simple joy of having everyone in one room again'' 的转述。"}]'::jsonb, '[{"word":"eve","cn":"前夕"},{"word":"envelope","cn":"信封"},{"word":"evil","cn":"邪恶的"},{"word":"pollution","cn":"污染"}]'::jsonb, 2, 'required3', 'U1');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'The Rio Carnival', 'The Rio Carnival in Brazil is one of the biggest and most colourful celebrations on Earth. Every year, just before the quiet season in the Christian calendar, the city of Rio fills with music, dancing and laughter. People dress up in bright carnival costumes and march along the streets, while samba dancers move to the beat in front of huge cheering crowds. The most famous part of the carnival is the samba parade, in which different groups compete to give the most amazing performance. Months of hard work go into the costumes and the dances, so for the dancers this single night is the result of a whole year''s effort. Visitors come from all over the world to enjoy the relaxing yet exciting atmosphere. For many of them, walking among the dancing crowds and feeling the energy of the music is an experience they will never forget. The carnival shows how a festival can bring strangers together to share pure joy.', '说明·里约狂欢节', 161, '[{"q":"What is the most famous part of the Rio Carnival?","answer":"D","options":["A quiet church service.","A firework display over the river.","A harvest feast in a town hall.","The samba parade where groups compete."],"explanation":"原文 ''The most famous part... is the samba parade, in which different groups compete'' 的转述。"},{"q":"Why is a single carnival night so important to the dancers?","answer":"A","options":["Because it represents a whole year of preparation.","Because it is the cheapest night of the year.","Because no one is watching them.","Because they can finally rest at home."],"explanation":"原文 ''the result of a whole year''s effort'' 的转述。"},{"q":"What does the carnival show, according to the writer?","answer":"B","options":["That festivals are a waste of time.","That a festival can unite strangers in shared joy.","That only locals can take part.","That dancing is dangerous."],"explanation":"末句 ''bring strangers together to share pure joy'' 的转述。"}]'::jsonb, '[{"word":"carnival","cn":"狂欢节"},{"word":"costume","cn":"服装"},{"word":"samba","cn":"桑巴舞"},{"word":"march","cn":"行进"}]'::jsonb, 2, 'required3', 'U1');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'La Tomatina: The Tomato Fight', 'La Tomatina is one of the strangest food festivals in the world. It takes place in the small Spanish town of Buñol every August. You might expect a food festival to be about eating, but this one is different, because nobody actually eats the tomatoes. Instead, the people throw them at one another! On the day of the festival, trucks full of soft tomatoes arrive in the town square, and at a given signal the great fight begins. The number of people taking part can reach up to twenty thousand, and the battle lasts for a whole exciting hour. When the signal sounds again, everyone stops at once. The most surprising thing is how clean the town looks afterwards. This is because the juice from the tomatoes is slightly acidic, which actually helps to clean the streets and walls. So although the fight looks messy, the town ends up cleaner than before, and everyone goes home tired but laughing.', '说明·西班牙番茄节', 159, '[{"q":"What is unusual about this food festival?","answer":"C","options":["Only children may join in.","It is held in the middle of winter.","People throw the food instead of eating it.","No food is brought to the town at all."],"explanation":"原文 ''nobody actually eats the tomatoes... they throw them at one another'' 的转述。"},{"q":"How long does the tomato fight last?","answer":"D","options":["A whole day.","Just a few seconds.","Three days and nights.","Around sixty minutes."],"explanation":"原文 ''lasts for a whole exciting hour'' 的转述。"},{"q":"Why is the town so clean after the fight?","answer":"A","options":["Because the tomato juice helps clean the surfaces.","Because the tomatoes are washed first.","Because few people take part.","Because it always rains afterwards."],"explanation":"原文 ''the juice... helps to clean the streets and walls'' 的转述。"}]'::jsonb, '[{"word":"signal","cn":"信号"},{"word":"battle","cn":"战斗"},{"word":"acidic","cn":"酸性的"},{"word":"messy","cn":"凌乱的"}]'::jsonb, 2, 'required3', 'U1');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'My Naadam Experience', 'Last summer I experienced the Naadam Festival in Inner Mongolia for the first time. The word "Naadam" means "games", and the festival is built around three events: horse racing, wrestling and archery. On the first morning, my friend Burin and I set off early. Everywhere I looked, I saw people wearing fancy Mongolian robes; some were feeding their horses while others chatted or took photographs. After the opening ceremony, the wrestling began. Mongolian wrestling has no rounds and no weight classes, and a wrestler loses the moment any part of his body above the knee touches the ground. Before each match, the competitors danced onto the field, waving their arms like eagles, and I was deeply moved by their strength and grace. I enjoyed the archery too, but the horse races were my favourite. I was surprised to learn that the young riders were boys and girls, chosen because lighter riders let the horses run faster. Celebrating Naadam with a local friend was an unforgettable experience.', '记叙·那达慕节体验', 166, '[{"q":"Which three events make up the Naadam Festival?","answer":"B","options":["Singing, dancing and cooking.","Racing on horses, wrestling and shooting with bows.","Football, swimming and running.","Guessing riddles, eating and shopping."],"explanation":"原文 ''three events: horse racing, wrestling and archery'' 的转述。"},{"q":"When does a Mongolian wrestler lose a match?","answer":"C","options":["When the round time runs out.","When he weighs too much.","As soon as he touches the ground with any part above his knee.","When he stops singing."],"explanation":"原文 ''loses the moment any part of his body above the knee touches the ground'' 的转述。"},{"q":"Why are the horse riders usually children?","answer":"D","options":["Because adults are not allowed.","Because children own the horses.","Because there are no adults in the area.","Because lighter riders help the horses run faster."],"explanation":"原文 ''chosen because lighter riders let the horses run faster'' 的转述。"}]'::jsonb, '[{"word":"wrestle","cn":"摔跤"},{"word":"grace","cn":"优雅"},{"word":"archery","cn":"射箭"},{"word":"set off","cn":"出发"}]'::jsonb, 2, 'required3', 'U1');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required3', 'U1', 'The Mid-Autumn Festival', 'The Mid-Autumn Festival is one of the most loved (1)____ in China. It falls in autumn, when the moon is at its roundest and brightest. On this night, families (2)____ together to admire the shining moon. A round moon is thought to (3)____ a happy and complete family, so people who live far away try hard to come home. The (4)____ food of this festival is the mooncake, a small round cake with sweet filling inside. Sharing mooncakes is a way of showing love and (5)____ to one another. Long ago, people also told (6)____ stories about a goddess who lives on the moon. Today, some families enjoy (7)____ riddles or lighting small lanterns as well. Although the customs may change over (8)____, the meaning of the festival stays the same. It is a (9)____ occasion that reminds everyone how important family is. To many Chinese people, no other night feels quite so (10)____.', 154, 2, '[{"q":"1","answer":"A","options":["festivals","machines","prices","noises"],"explanation":"loved festivals 受喜爱的节日。"},{"q":"2","answer":"B","options":["break","gather","sell","hide"],"explanation":"gather together 聚在一起。"},{"q":"3","answer":"C","options":["destroy","lose","represent","waste"],"explanation":"represent 象征。"},{"q":"4","answer":"D","options":["empty","angry","broken","typical"],"explanation":"typical food 典型食物。"},{"q":"5","answer":"A","options":["gratitude","anger","fear","noise"],"explanation":"love and gratitude 爱与感激。"},{"q":"6","answer":"B","options":["silent","ancient","modern","foreign"],"explanation":"ancient stories 古老的故事。"},{"q":"7","answer":"C","options":["selling","throwing","guessing","losing"],"explanation":"guessing riddles 猜谜。"},{"q":"8","answer":"D","options":["money","books","shoes","time"],"explanation":"change over time 随时间改变。"},{"q":"9","answer":"A","options":["joyful","boring","useless","terrible"],"explanation":"joyful occasion 欢乐的日子。"},{"q":"10","answer":"B","options":["empty","special","noisy","cheap"],"explanation":"special 特别的。"}]'::jsonb, 1);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required3', 'U1', 'The Lantern Festival', 'The Lantern Festival marks the (1)____ day of the Chinese New Year celebrations. As night falls, towns and parks are (2)____ with thousands of colourful lanterns. Families walk slowly through the streets, (3)____ the beautiful lights and feeling the warm holiday spirit. One of the most popular activities is (4)____ riddles, which are often written on the lanterns themselves. If you can give the right (5)____, you may win a small prize. Another (6)____ of the festival is eating tangyuan, sweet balls of sticky rice that (7)____ family reunion. In some towns, people perform a fire dragon dance, and the (8)____ dragon lights up the whole square. Many ancient poets wrote about this festival, describing the (9)____ scenes and the happy crowds. Even today, the Lantern Festival keeps its (10)____ charm and brings people closer together.', 136, 2, '[{"q":"1","answer":"C","options":["empty","cheap","last","silent"],"explanation":"the last day 最后一天。"},{"q":"2","answer":"D","options":["broken","emptied","closed","decorated"],"explanation":"decorated with lanterns 用灯笼装饰。"},{"q":"3","answer":"A","options":["admiring","selling","hiding","losing"],"explanation":"admiring the lights 欣赏灯光。"},{"q":"4","answer":"B","options":["selling","guessing","throwing","burning"],"explanation":"guessing riddles 猜谜。"},{"q":"5","answer":"C","options":["price","noise","answer","weather"],"explanation":"the right answer 正确答案。"},{"q":"6","answer":"D","options":["mistake","price","problem","feature"],"explanation":"a feature of 一个特色。"},{"q":"7","answer":"A","options":["represent","destroy","forget","waste"],"explanation":"represent reunion 象征团圆。"},{"q":"8","answer":"B","options":["sleeping","dancing","broken","frozen"],"explanation":"dancing dragon 舞动的龙,现在分词作定语。"},{"q":"9","answer":"C","options":["boring","empty","joyful","silent"],"explanation":"joyful scenes 欢乐的场面。"},{"q":"10","answer":"D","options":["false","cheap","broken","unique"],"explanation":"unique charm 独特魅力。"}]'::jsonb, 2);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required3', 'U1', 'Thanksgiving Dinner', 'Thanksgiving is a warm autumn (1)____ celebrated mainly in North America. It began long ago as a way for people to give thanks for a good (2)____ of food. On this day, families travel from near and far to (3)____ around one table. The (4)____ dish is a large roast turkey, served with mashed potatoes, pumpkin pie and other treats. Before the meal, many families take turns saying what they are (5)____ for. After dinner, some people watch sports games on television, while others simply (6)____ and talk for hours. To be (7)____, the food is wonderful, but the best part is being with the people you (8)____. The holiday reminds us to slow down and feel (9)____ for what we have. In a busy world, such (10)____ moments are truly precious.', 132, 2, '[{"q":"1","answer":"A","options":["festival","machine","price","noise"],"explanation":"autumn festival 秋季节日。"},{"q":"2","answer":"B","options":["price","harvest","noise","mistake"],"explanation":"a good harvest 好收成。"},{"q":"3","answer":"C","options":["break","hide","gather","lose"],"explanation":"gather around 围坐。"},{"q":"4","answer":"D","options":["empty","broken","silent","main"],"explanation":"the main dish 主菜。"},{"q":"5","answer":"A","options":["grateful","angry","afraid","bored"],"explanation":"grateful for 感激。"},{"q":"6","answer":"B","options":["sell","laugh","lose","break"],"explanation":"laugh and talk 欢笑交谈。"},{"q":"7","answer":"C","options":["late","rich","frank","busy"],"explanation":"to be frank 坦白说。"},{"q":"8","answer":"D","options":["sell","forget","lose","love"],"explanation":"the people you love 你爱的人。"},{"q":"9","answer":"A","options":["grateful","angry","afraid","bored"],"explanation":"feel grateful 感到感激。"},{"q":"10","answer":"B","options":["empty","quiet","noisy","cheap"],"explanation":"quiet moments 安静的时刻。"}]'::jsonb, 3);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required3', 'U1', 'A Christmas to Remember', 'For me, the most (1)____ festival of the year is Christmas. A few weeks before, families (2)____ their homes with bright lights and a tall green tree. I can never take my eyes off the (3)____ lights on the trees everywhere. On Christmas Eve, people often (4)____ carols outside, wishing one another a merry Christmas. Children hang up their socks and wait for (5)____ to arrive while they sleep. In the morning, everyone opens the gifts (6)____ under the tree, and the room fills with happy cries. Later, the whole family shares a big meal, with a roast turkey at its (7)____. The day is full of (8)____ faces and kind words. To me, Christmas is not really about the (9)____ but about the warm feeling of being together. It is a (10)____ that I look forward to all year long.', 141, 2, '[{"q":"1","answer":"C","options":["empty","boring","special","useless"],"explanation":"the most special festival 最特别的节日。"},{"q":"2","answer":"D","options":["destroy","sell","lose","decorate"],"explanation":"decorate their homes 装饰家。"},{"q":"3","answer":"A","options":["shining","broken","frozen","sleeping"],"explanation":"shining lights 闪亮的灯,现在分词作定语。"},{"q":"4","answer":"B","options":["throw","sing","sell","burn"],"explanation":"sing carols 唱颂歌。"},{"q":"5","answer":"C","options":["prices","noises","presents","errors"],"explanation":"wait for presents 等礼物。"},{"q":"6","answer":"D","options":["sold","thrown","lost","left"],"explanation":"gifts left under the tree 放在树下的礼物。"},{"q":"7","answer":"A","options":["centre","price","noise","weather"],"explanation":"at its centre 在其中心。"},{"q":"8","answer":"B","options":["angry","smiling","afraid","bored"],"explanation":"smiling faces 微笑的脸,现在分词作定语。"},{"q":"9","answer":"C","options":["prices","noises","gifts","errors"],"explanation":"about the gifts 关于礼物。"},{"q":"10","answer":"D","options":["mistake","price","problem","holiday"],"explanation":"a holiday 一个节日。"}]'::jsonb, 4);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required3', 'U1', 'Coming-of-Age Day', 'In some countries, young people celebrate a special (1)____ when they become adults. On Coming-of-Age Day, those who have just turned twenty (2)____ traditional costumes and attend a public ceremony. It is an (3)____ and proud moment for the young people and their families. During the ceremony, the new adults receive (4)____ from older members of the community. Speakers remind them that being an adult means taking on more (5)____ for themselves and for society. After the (6)____ part is over, friends gather to take photographs and celebrate (7)____. To many young people, this day (8)____ the start of a new chapter in life. It is a (9)____ that helps them understand who they are becoming. Even years later, they often remember that special (10)____ with a warm smile.', 129, 2, '[{"q":"1","answer":"A","options":["occasion","machine","price","noise"],"explanation":"a special occasion 特别的日子。"},{"q":"2","answer":"B","options":["throw","wear","sell","lose"],"explanation":"wear costumes 穿服装。"},{"q":"3","answer":"C","options":["empty","boring","exciting","silent"],"explanation":"exciting moment 令人激动的时刻。"},{"q":"4","answer":"D","options":["mistakes","noises","prices","congratulations"],"explanation":"receive congratulations 接受祝贺。"},{"q":"5","answer":"A","options":["responsibility","weather","price","noise"],"explanation":"more responsibility 更多责任。"},{"q":"6","answer":"B","options":["broken","formal","empty","silent"],"explanation":"the formal part 正式的部分。"},{"q":"7","answer":"C","options":["sadly","angrily","happily","quietly"],"explanation":"celebrate happily 高兴地庆祝。"},{"q":"8","answer":"D","options":["destroys","wastes","loses","marks"],"explanation":"marks the start 标志着开始。"},{"q":"9","answer":"A","options":["custom","price","noise","error"],"explanation":"a custom 一种习俗。"},{"q":"10","answer":"B","options":["price","day","noise","error"],"explanation":"that special day 那个特别的日子。"}]'::jsonb, 5);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required3', 'U1', 'Festivals and Shopping', 'In recent years, many festivals have become more and more (1)____. Businesses take advantage of the holidays to sell all kinds of (2)____. Online shopping websites and social media apps make it much (3)____ for people to spend money on gifts for their loved ones. Some people worry that festivals are losing their true (4)____, and that customs may slowly (5)____ away. They believe a festival should be about feelings, not (6)____. Others argue that spending more is actually (7)____ for the economy and brings happiness to many people. Both sides make (8)____ points. Perhaps the wisest choice is to enjoy the gifts while remembering what really (9)____: the time we spend with the people we care about. In the end, no festival is truly (10)____ without that warm human spirit.', 131, 2, '[{"q":"1","answer":"C","options":["empty","silent","commercial","broken"],"explanation":"more commercial 更商业化。"},{"q":"2","answer":"D","options":["noises","prices","mistakes","products"],"explanation":"sell products 卖商品。"},{"q":"3","answer":"A","options":["easier","worse","harder","slower"],"explanation":"much easier 更容易。"},{"q":"4","answer":"B","options":["price","meaning","noise","weather"],"explanation":"true meaning 真正的意义。"},{"q":"5","answer":"C","options":["grow","build","fade","rise"],"explanation":"fade away 逐渐消失。"},{"q":"6","answer":"D","options":["love","joy","peace","money"],"explanation":"not money 而不是金钱。"},{"q":"7","answer":"A","options":["good","bad","empty","broken"],"explanation":"good for the economy 对经济有益。"},{"q":"8","answer":"B","options":["empty","fair","silent","broken"],"explanation":"fair points 合理的观点。"},{"q":"9","answer":"C","options":["breaks","loses","matters","sells"],"explanation":"what really matters 真正重要的。"},{"q":"10","answer":"D","options":["broken","empty","silent","complete"],"explanation":"truly complete 真正完整。"}]'::jsonb, 6);
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U1 听力·对话 Choosing a Festival to Visit', '必修三 U1 · dialogue', 3, 'Lucy: We have a free week in spring. Which festival should we travel to see?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U1 听力·短文 The Story of Halloween', '必修三 U1 · passage', 2, 'Halloween is celebrated on the last day of October. Although it began with religious origins long ago, it has slowly become an exciting festival, especially for children. On this night, children dress up in funny or frightening costumes and go from house to house asking for sweets. People carve faces into large orange pumpkins and place lights inside them. Some families decorate their homes and tell scary stories in the dark. The festival is no longer about its old religious meaning; today it is mostly about having fun together. For many children, it is one of the most enjoyable nights of the whole year.', '万圣节在10月最后一天庆祝;虽然很久以前源于宗教,但如今已渐渐变成一个有趣的节日,尤其受孩子喜爱;这一夜孩子们打扮成搞笑或吓人的样子,挨家挨户讨糖;人们在橙色大南瓜上刻脸并放灯;有些家庭装饰房屋、在黑暗中讲恐怖故事;如今它已不再关乎旧的宗教含义,而主要是大家一起玩乐;对许多孩子来说,这是一年中最快乐的夜晚之一。', 'uk_female', '[{"q":"When is Halloween celebrated?","type":"choice","answer":"D","options":["In the middle of summer.","On New Year''s Eve.","During the spring harvest.","On the last day of October."]},{"q":"How has Halloween changed over time?","type":"choice","answer":"A","options":["It has become a fun festival, especially for children.","It has been cancelled.","It has become a quiet religious day.","It has moved to winter."]},{"q":"What do children do on Halloween night?","type":"choice","answer":"B","options":["They go to bed early.","They dress up and ask for sweets from house to house.","They light firecrackers.","They watch a samba parade."]},{"q":"What do people do with pumpkins?","type":"choice","answer":"C","options":["They eat them raw.","They throw them away.","They carve faces into them and put lights inside.","They sell them at a fair."]},{"q":"What is Halloween mostly about today?","type":"choice","answer":"D","options":["Its old religious meaning.","Giving thanks for the harvest.","Driving away evil spirits.","Having fun together."]}]'::jsonb, '[]'::jsonb, 'short', 'required3', 'U1');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U1 听力·对话 At the Carnival', '必修三 U1 · dialogue', 3, 'Reporter: Excuse me, you''re wearing such a bright costume. Are you enjoying the carnival?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U1 听力·短文 Mongolian Wrestling', '必修三 U1 · passage', 2, 'Wrestling is one of the most important events at the Naadam Festival. Mongolian wrestling is quite different from the wrestling you see at the Olympic Games. There are no rounds, and the wrestlers are not separated by weight, so a smaller man may face a much larger one. A wrestler loses the match as soon as any part of his body above the knee touches the ground. Before each match, the competitors dance onto the field, waving their arms as if they were eagles. Watching their strength and grace, many visitors feel deeply moved. For the Mongolian people, wrestling is far more than a sport; it is a proud part of their culture.', '摔跤是那达慕节最重要的项目之一;蒙古摔跤与奥运会的摔跤很不一样;没有回合,也不按体重分级,所以小个子可能对上大块头;一旦膝盖以上的任何部位触地,摔跤手就算输;每场比赛前,选手们像雄鹰一样挥臂舞入场地;看着他们的力量与优雅,许多游客深受感动;对蒙古人来说,摔跤远不只是一项运动,而是他们文化中令人自豪的一部分。', 'uk_female', '[{"q":"How is Mongolian wrestling different from Olympic wrestling?","type":"choice","answer":"B","options":["It is played with a ball.","It has no rounds and no weight classes.","It is only for children.","It lasts exactly one hour."]},{"q":"When does a wrestler lose the match?","type":"choice","answer":"C","options":["When the time runs out.","When he stops singing.","When a part of his body above the knee touches the ground.","When he leaves the field."]},{"q":"What do the competitors do before each match?","type":"choice","answer":"D","options":["They sit and rest quietly.","They eat a large meal.","They light firecrackers.","They dance onto the field, waving their arms like eagles."]},{"q":"How do many visitors feel while watching?","type":"choice","answer":"A","options":["Deeply moved by the strength and grace.","Bored and sleepy.","Angry and upset.","Cold and hungry."]},{"q":"What does wrestling mean to the Mongolian people?","type":"choice","answer":"B","options":["Just a simple game.","A proud part of their culture.","A boring duty.","A modern foreign sport."]}]'::jsonb, '[]'::jsonb, 'short', 'required3', 'U1');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U1 听力·对话 Thanksgiving Abroad', '必修三 U1 · dialogue', 3, 'Song Lin: Max, you look happy. Did you enjoy the festival?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U1 听力·短文 Enjoying Festivals Politely', '必修三 U1 · passage', 2, 'Here is some simple advice for anyone visiting a festival in another country. First, learn a little about the festival''s customs before you go, so you understand what is happening. Second, dress in a way that fits the occasion; at some ceremonies people wear traditional costumes. Third, always show respect for local traditions, even if they seem strange to you. If you are not sure what to do, just watch the people around you and follow them politely. Remember that every custom has a meaning behind it. By joining in with an open heart, you will not only enjoy the festival more, but also make new friends and feel truly welcome.', '给到外国参加节日的人一些简单建议:第一,去之前先了解一点节日习俗,以便明白正在发生什么;第二,穿着要合乎场合,有些仪式上人们会穿传统服装;第三,即使某些传统看起来奇怪,也要始终尊重当地传统;若不确定该怎么做,就观察周围的人并礼貌地跟着做;记住每个习俗背后都有含义;以开放的心态参与,你不仅会更享受节日,还会结交新朋友、感到真正受欢迎。', 'uk_female', '[{"q":"Who is this advice for?","type":"choice","answer":"D","options":["Only festival organisers.","Only small children.","Only news reporters.","Anyone visiting a festival in another country."]},{"q":"What should you do before you go to the festival?","type":"choice","answer":"A","options":["Learn a little about its customs.","Buy as many gifts as possible.","Bring lots of food.","Tell everyone your opinion."]},{"q":"What does the speaker say about local traditions?","type":"choice","answer":"B","options":["You should change them.","You should always show respect for them.","You should ignore them.","You should laugh at them."]},{"q":"What should you do if you are unsure what to do?","type":"choice","answer":"C","options":["Leave immediately.","Complain loudly.","Watch the people around you and follow politely.","Do whatever you like."]},{"q":"What is the benefit of joining in with an open heart?","type":"choice","answer":"D","options":["You spend much more money.","You feel tired and bored.","You learn nothing new.","You enjoy the festival more and make new friends."]}]'::jsonb, '[]'::jsonb, 'short', 'required3', 'U1');
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit) VALUES (10, 'Describe a Festival You Like(介绍一个你喜欢的节日)', 'My Favourite Festival', '假设你叫李华,某英文网站正在征集''我最喜欢的节日''短文。请用英语写一篇约100词的文章,内容包括:① 节日名称,以及你和谁、在何时何地庆祝;② 你们参加的主要活动;③ 你对这个节日的感受。注意:恰当使用现在分词(V-ing)作定语或表语(如 exciting dragon dances / families celebrating the festival)。', 'Suppose you are Li Hua. An English website is collecting short articles on "My Favourite Festival". Write a passage of about 100 words including: 1) the name of the festival, and when, where and with whom you celebrate it; 2) the main activities you take part in; 3) how you feel about the festival. Try to use the -ing form (V-ing) correctly as an attribute or a predicative.', '["点明节日与庆祝的时间/地点/同伴(I celebrate … with … every …)","描述主要活动(We … / Families celebrating … enjoy …)","表达对节日的感受(For me, it is always exciting / amazing …)","恰当使用 V-ing 作定语/表语(exciting dances / shining lanterns / the moon is amazing)"]'::jsonb, 70, 100, 'My favourite festival is the Mid-Autumn Festival. Every autumn, I celebrate it with my whole family at my grandmother''s house. On that special night, the round moon shining in the sky is truly amazing. After a big dinner, we sit in the yard, admiring the bright moon and enjoying sweet mooncakes together. The younger children, running around with small lanterns, fill the air with laughter. My grandmother always tells us touching old stories about the moon. For me, the festival is not really about the food; it is the warm feeling of having everyone together that I find most exciting. I look forward to it every year.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["The round moon shining in the sky is truly amazing.","The younger children, running around with small lanterns, fill the air with laughter.","We sit in the yard, admiring the bright moon and enjoying sweet mooncakes together.","It is the warm feeling of having everyone together that I find most exciting."]'::jsonb, '[{"wrong":"The dragon dances were very excited.","correct":"The dragon dances were very exciting.","note":"事物用 -ing(exciting),人才用 -ed(excited)。"},{"wrong":"The children playing was very happy.","correct":"The children playing were very happy.","note":"主语 children 复数,谓语用 were;playing 是后置定语。"},{"wrong":"I saw many people wore costumes.","correct":"I saw many people wearing costumes.","note":"后置定语表主动/进行用 V-ing,不用过去式动词。"}]'::jsonb, '【介绍节日结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content) VALUES (10, 'required3', 'U1', '{"title":"现在分词(V-ing)作表语和定语 速查","intro":"现在分词(V-ing)表示主动、正在进行的动作或性质。作表语描述事物给人的感受(物用 -ing,人用 -ed);作前置/后置定语,相当于一个主动的形容词或定语从句(who/which is doing)。","table":{"headers":["用法","位置 / 例句 / 等价"],"rows":[["作表语","be + V-ing:The film is amazing.(物的性质;人则用 -ed:I am amazed.)"],["前置定语","V-ing + 名词:exciting news / the rising sun / running water(主动·进行)"],["后置定语","名词 + V-ing 短语:the man standing there = who is standing there"],["V-ing vs -ed","物用 -ing(exciting),人用 -ed(excited);The news is exciting / I am excited."]]},"specialRules":[{"rule":"描述事物''令人……''的性质或感受 → 用 V-ing","mark":"These lanterns are amazing.(amazing 修饰物)"},{"rule":"描述人''感到……'' → 用 -ed","mark":"I was amazed by the lanterns.(amazed 修饰人)"},{"rule":"后置定语 = 主动的定语从句(who/which is doing),被修饰名词是动作发出者","mark":"families celebrating the festival = who are celebrating it"},{"rule":"短语作后置定语;单个分词常前置","mark":"the shining moon(前置) / the moon shining brightly(短语后置)"}],"why":["现在分词来自动词,保留''主动·进行''的意义:作定语时,名词是动作的发出者(the running water = water that is running);作表语时,说明主语本身具有''使人……''的性质,所以物用 -ing、人用 -ed。"],"gaokaoPoints":["-ing 与 -ed 的辨析(物 vs 人:exciting/excited、boring/bored、moving/moved)是语法填空与单选高频考点。","现在分词作后置定语 vs 过去分词作后置定语:主动/进行用 V-ing(the man standing),被动/完成用 V-ed(the gifts left under the tree)。"],"examVsReal":[{"exam":"The story is touching.(考试)","real":"口语里也常说 The story is so touching / really moving","note":"考试重点是分清 -ing(物)与 -ed(人),口语用法一致但更随意"},{"exam":"the families celebrating the festival(后置定语·书面)","real":"the families who are celebrating the festival","note":"考试爱用分词压缩从句,口语里两种都自然"}]}'::jsonb);
